# name: early_session_yes_gap
# description: Yes rate on trials with trial_index < 118 (first quarter of the session) minus yes rate on later trials; observed < null means people start out more conservative than later in the session, a warm-up drift the stationary model cannot produce (observed > null: they start more liberal).
def test_statistic(df):
    ti = df["trial_index"].astype(float).values
    r = df["rating"].astype(float).values
    e = ti < 118
    if e.sum() == 0 or (~e).sum() == 0:
        return 0.0
    return float(r[e].mean() - r[~e].mean())

# name: n4_set_mean_variance
# description: Variance across four-example sets of each set's mean yes rate; observed > null means people's breadth of generalization differs more between four-example sets than the memory-drop model predicts (observed < null: the model over-differentiates four-example sets).
def test_statistic(df):
    s = df["number_set"].astype(str)
    n = s.str.count(",").values + 1
    m = n == 4
    if m.sum() == 0:
        return 0.0
    g = df.loc[m, "rating"].astype(float).groupby(s[m].values).mean()
    return float(g.var(ddof=0))

# name: same_half_magnitude_gap
# description: On 2-4-example sets whose examples all lie in one half of 1-100 (all <=50 or all >50), yes rate for targets in that same half minus targets in the other half; observed > null means people treat 'small numbers'/'big numbers' as a category more sharply than the model's distance band (observed < null: the model over-sharpens magnitude).
def test_statistic(df):
    sets = df["number_set"].astype(str).values
    u, inv = np.unique(sets, return_inverse=True)
    K = len(u)
    half = np.full(K, -1)
    for i, s in enumerate(u):
        e = [int(x) for x in s.split(",")]
        if len(e) >= 2:
            if all(x <= 50 for x in e):
                half[i] = 0
            elif all(x > 50 for x in e):
                half[i] = 1
    t = df["target"].astype(int).values
    r = df["rating"].astype(float).values
    h = half[inv]
    th = (t > 50).astype(int)
    a = (h >= 0) & (th == h)
    b = (h >= 0) & (th != h)
    if a.sum() == 0 or b.sum() == 0:
        return 0.0
    return float(r[a].mean() - r[b].mean())
